// Este flujo ahora solo maneja recordatorios por TIEMPO (PAGO_SALDO,
// CHECK_IN, POST_VIAJE). VOUCHER y CONTRATO se sacaron de acá: se emiten y
// avisan al instante desde el botón del front (ver Flujo7_DocumentoEmitido,
// disparado por webhook desde el back apenas se genera el documento) en vez
// de esperar a este cron de las 9AM.
const r = $json;
const rsv = r.reserva || {};
const cli = rsv.cliente || {};
const v = rsv.cotizacion?.viaje || {};
const ruta = (v.origen?.codigoIATA && v.destino?.codigoIATA)
  ? `${v.origen.codigoIATA} → ${v.destino.codigoIATA}`
  : 'tu viaje';
const fechaViaje = rsv.fechaViaje ? new Date(rsv.fechaViaje).toLocaleDateString('es-AR') : '';
const saldoPendiente = (Number(rsv.montoFinal) - Number(rsv.saldoPagado)).toFixed(2);
const tel = (cli.telefono || '').replace(/^whatsapp:/, '');

let mensaje = '';

switch (r.tipo) {
  case 'PAGO_SALDO':
    mensaje = `🧾 *Recordatorio de pago — STG*\n\nHola ${cli.nombre}, te recordamos que tenés un saldo pendiente de *USD ${saldoPendiente}* para tu reserva ${rsv.numeroReserva} (${ruta} - ${fechaViaje}).\n\nPara evitar la cancelación automática, regularizá el pago hasta 7 días antes del viaje. Cualquier consulta, escribinos por acá. ✈️`;
    break;
  case 'CHECK_IN':
    mensaje = `✈️ *¡Mañana viajás!*\n\nHola ${cli.nombre}, recordá hacer el check-in online de tu vuelo de mañana (${ruta} - ${fechaViaje}). La mayoría de las aerolíneas lo habilitan 24-48 horas antes.\n\n¡Buen viaje! 🌍`;
    break;
  case 'POST_VIAJE':
    mensaje = `🎉 *¿Qué tal el viaje?*\n\nHola ${cli.nombre}, esperamos que la hayas pasado increíble en ${v.destino?.nombre || 'tu destino'}. Nos encantaría saber cómo fue tu experiencia para seguir mejorando.\n\n¿Nos dejás un comentario o una calificación? 🙏`;
    break;
  default:
    mensaje = `Hola ${cli.nombre}, te escribimos desde STG sobre tu reserva ${rsv.numeroReserva}.`;
}

if (!tel) return []; // sin teléfono no podemos avisar

return [{ json: {
  recordatorioId: r.id, tipo: r.tipo, telefono: tel, mensaje, reservaNumero: rsv.numeroReserva
} }];
